const functions = require('firebase-functions');
const admin = require('firebase-admin');
admin.initializeApp();

const REGION = 'asia-south1';

// 1. Auto-add sample expenses for new user
exports.addSampleExpensesOnSignup = functions.region(REGION).auth.user().onCreate(async (user) => {
  const userId = user.uid;
  const db = admin.firestore();
  
  const samples = [
    { title: 'Breakfast', category: 'Food', amount: 40, date: new Date().toISOString().split('T')[0] },
    { title: 'Bus ticket', category: 'Travel', amount: 15, date: new Date().toISOString().split('T')[0] },
    { title: 'Tea', category: 'Food', amount: 10, date: new Date().toISOString().split('T')[0] },
    { title: 'Notes', category: 'Essentials', amount: 20, date: new Date().toISOString().split('T')[0] },
    { title: 'Internet Recharge', category: 'Utilities', amount: 199, date: new Date().toISOString().split('T')[0] },
  ];

  const batch = db.batch();
  samples.forEach(s => {
    const ref = db.collection('expenses').doc();
    batch.set(ref, {
      ...s,
      userId,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAt: admin.firestore.FieldValue.serverTimestamp()
    });
  });

  batch.set(db.collection('users').doc(userId), {
    customCategories: [],
    budgets: {},
    recurringExpenses: [],
    appliedRecurringMonths: []
  });

  return batch.commit();
});

// 2. Budget exceed notifications (Mock implementation)
exports.sendBudgetAlert = functions.region(REGION).firestore
  .document('expenses/{expenseId}')
  .onCreate(async (snapshot, context) => {
    const expense = snapshot.data();
    const userId = expense.userId;
    const db = admin.firestore();
    
    // Get current month budget
    const month = expense.date.substring(0, 7);
    const userDoc = await db.collection('users').doc(userId).get();
    const userData = userDoc.data();
    const budget = userData.budgets && userData.budgets[month];
    
    if (budget) {
      // Calculate total spent (Simplified)
      const expensesSnap = await db.collection('expenses')
        .where('userId', '==', userId)
        .where('date', '>=', month + '-01')
        .where('date', '<=', month + '-31')
        .get();
      
      let totalSpent = 0;
      expensesSnap.forEach(doc => totalSpent += doc.data().amount);
      
      if (totalSpent > budget.totalBudget) {
        console.log(`User ${userId} exceeded budget: ${totalSpent}/${budget.totalBudget}`);
        // Here you would send a FCM notification or Email
      }
    }
  });

// 3. Daily cleanup for invalid data
exports.cleanupInvalidExpenses = functions.region(REGION).pubsub.schedule('every 24 hours').onRun(async (context) => {
  const db = admin.firestore();
  const invalidSnap = await db.collection('expenses')
    .where('amount', '<=', 0)
    .get();
  
  const batch = db.batch();
  invalidSnap.forEach(doc => batch.delete(doc.ref));
  return batch.commit();
});

// 4. Monthly summary generator
exports.generateMonthlyReport = functions.region(REGION).pubsub.schedule('0 0 1 * *').onRun(async (context) => {
  // Logic to generate and save monthly reports for all users
  return null;
});

const fs = require('fs');
const path = require('path');
const data = JSON.parse(fs.readFileSync('lint_output.json', 'utf8'));

data.forEach(file => {
  const errors = file.messages.filter(m => m.severity === 2);
  if (errors.length > 0) {
    console.log(`File: ${path.relative(process.cwd(), file.filePath)}`);
    errors.forEach(e => {
      console.log(`  Line ${e.line}:${e.column} - ${e.message} (${e.ruleId})`);
    });
  }
});

import { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider } from './context/AuthContext';
import { ProtectedRoute } from './components/ProtectedRoute';
import { Login } from './pages/Login';
import { Signup } from './pages/Signup';
import { ForgotPassword } from './pages/ForgotPassword';
import { Dashboard } from './pages/Dashboard';
import { Transactions } from './pages/Transactions';
import { Insights } from './pages/Insights';
import { BudgetSettings } from './pages/BudgetSettings';
import { FamilyWallet } from './pages/FamilyWallet';
import { FixedExpenses } from './pages/FixedExpenses';
import { Reports } from './pages/Reports';
import { YearlySummary } from './pages/YearlySummary';
import { BudgetAudit } from './pages/BudgetAudit';
import { useExpenseTracker } from './hooks/useExpenseTracker';
import { Sidebar } from './components/Sidebar';
import { TopBar } from './components/TopBar';
import { Modal } from './components/ui/Modal';
import { AddExpenseForm } from './components/AddExpenseForm';
import { Transaction } from './types';

function AppContent() {
  const {
    state,
    currentMonth,
    setCurrentMonth,
    currentMonthTransactions,
    totalSpent,
    currentBudget,
    remainingBalance,
    upiSpent,
    cashSpent,
    todaySpent,
    availableMonths,
    categories,
    addTransaction,
    bulkAddTransactions,
    editTransaction,
    deleteTransaction,
    isLoaded,
    updateBudget,
    carryForwardBudget,
    previousMonthRemaining,
    updateSavings,
    addCustomCategory,
    deleteCustomCategory,
    // Family wallet
    addFamilyMember,
    removeFamilyMember,
    modifyFamilyMemberAmount,
    transferMainToFamily,
    transferBetweenFamily,
    transferFamilyToMain,
    hasLocalData,
    syncLocalData,
    // Recurring
    addRecurringExpense,
    editRecurringExpense,
    deleteRecurringExpense,
    toggleRecurringExpense,
    totalFixedExpenses,
    upiBudget,
    cashBudget,
    upiRemaining,
    cashRemaining,
    transferBetweenModes,
    addMissingAmount,
    updateMissingAmount,
    totalMissing,
    todayMissing
  } = useExpenseTracker();

  const [currentTab, setCurrentTab] = useState<'dashboard' | 'transactions' | 'insights' | 'settings' | 'family' | 'fixed-expenses' | 'reports' | 'yearly-summary' | 'budget-audit'>('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);



  const handleSaveExpense = async (data: any) => {
    if (editingTransaction) {
      await editTransaction(editingTransaction.id, data);
    } else {
      await addTransaction(data);
    }
    setIsAddModalOpen(false);
  };

  if (!isLoaded) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <Sidebar 
        currentTab={currentTab} 
        onTabChange={setCurrentTab} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <TopBar 
          currentMonth={currentMonth} 
          onMonthChange={setCurrentMonth}
          availableMonths={availableMonths}
          onMenuClick={() => setIsSidebarOpen(true)}
        hasLocalData={hasLocalData}
        onSync={syncLocalData}
      />

        <main className="flex-1 overflow-y-auto p-4 md:p-6 lg:p-8">

          {currentTab === 'dashboard' && (
            <Dashboard
              totalBudget={currentBudget}
              totalSpent={totalSpent}
              remainingBalance={remainingBalance}
              upiSpent={upiSpent}
              cashSpent={cashSpent}
              todaySpent={todaySpent}
              recentTransactions={[...currentMonthTransactions].sort((a, b) => {
                const dateCompare = b.date.localeCompare(a.date);
                if (dateCompare !== 0) return dateCompare;
                // Secondary sort by createdAt if both have it
                const timeA = (a.createdAt as any)?.seconds || 0;
                const timeB = (b.createdAt as any)?.seconds || 0;
                return timeB - timeA;
              }).slice(0, 5)}
              onAddExpense={() => setIsAddModalOpen(true)}
              onViewAll={() => setCurrentTab('transactions')}
              onEdit={(t) => {
                setEditingTransaction(t);
                setIsAddModalOpen(true);
              }}
              onDelete={deleteTransaction}
              allBudgets={state.budgets}
              currentMonth={currentMonth}
              upiRemaining={upiRemaining}
              cashRemaining={cashRemaining}
              onAddMissingAmount={addMissingAmount}
              onUpdateBudget={updateBudget}
              allTransactions={state.transactions}
              upiBudget={upiBudget}
              cashBudget={cashBudget}
              totalMissing={totalMissing}
              todayMissing={todayMissing}
            />
          )}

          {currentTab === 'transactions' && (
            <Transactions 
              transactions={state.transactions}
              categories={categories}
              onAdd={() => setIsAddModalOpen(true)}
              onEdit={(t) => {
                setEditingTransaction(t);
                setIsAddModalOpen(true);
              }}
              onDelete={deleteTransaction}
              onImport={bulkAddTransactions}
            />
          )}



          {currentTab === 'family' && (
            <FamilyWallet
              familyMembers={state.familyMembers}
              currentBudget={currentBudget}
              onAddMember={addFamilyMember}
              onRemoveMember={removeFamilyMember}
              onModifyAmount={modifyFamilyMemberAmount}
              onTransferBetweenFamily={transferBetweenFamily}
              onTransferFamilyToMain={transferFamilyToMain}
              onTransferMainToFamily={transferMainToFamily}
            />
          )}


          {currentTab === 'insights' && (
            <Insights 
              transactions={state.transactions}
              currentMonth={currentMonth}
              totalBudget={currentBudget}
            />
          )}

          {currentTab === 'settings' && (
            <BudgetSettings 
              currentMonth={currentMonth}
              monthlyBudget={state.budgets[currentMonth] || null}
              categories={categories}
              onUpdateBudget={updateBudget}
              onAddCategory={addCustomCategory}
              onDeleteCategory={deleteCustomCategory}
              previousMonthRemaining={previousMonthRemaining}
              onCarryForward={carryForwardBudget}
              savings={state.savings}
              onUpdateSavings={updateSavings}
              onTransferModes={async (a, f) => { await transferBetweenModes(a, f); }}
              upiBudget={upiBudget}
              cashBudget={cashBudget}
            />
          )}

          {currentTab === 'fixed-expenses' && (
            <FixedExpenses
              recurringExpenses={state.recurringExpenses}
              categories={categories}
              totalFixedExpenses={totalFixedExpenses}
              onAdd={addRecurringExpense}
              onEdit={editRecurringExpense}
              onDelete={deleteRecurringExpense}
              onToggle={toggleRecurringExpense}
            />
          )}

          {currentTab === 'reports' && (
            <Reports
              transactions={currentMonthTransactions}
              totalBudget={currentBudget}
              savings={state.savings}
              monthlyBudget={state.budgets[currentMonth]}
              currentMonth={currentMonth}
              allTransactions={state.transactions}
            />
          )}

          {currentTab === 'yearly-summary' && (
            <YearlySummary
              transactions={state.transactions}
              currentMonth={currentMonth}
            />
          )}

          {currentTab === 'budget-audit' && (
            <BudgetAudit 
              state={state}
              allTransactions={state.transactions}
              onUpdateMissingAmount={updateMissingAmount}
            />
          )}
        </main>
      </div>

      <Modal
        isOpen={isAddModalOpen}
        onClose={() => setIsAddModalOpen(false)}
        title={editingTransaction ? 'Edit Expense' : 'Add Expense'}
      >
        <AddExpenseForm
          categories={categories}
          onSave={handleSaveExpense}
          onCancel={() => setIsAddModalOpen(false)}
          initialData={editingTransaction || undefined}
        />
      </Modal>
    </div>
  );
}

export function App() {
  return (
    <AuthProvider>
      <Router future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
        <Toaster position="top-right" />
        <Routes>
          <Route path="/login" element={<Login />} />
          <Route path="/signup" element={<Signup />} />
          <Route path="/forgot-password" element={<ForgotPassword />} />
          <Route 
            path="/dashboard" 
            element={
              <ProtectedRoute>
                <AppContent />
              </ProtectedRoute>
            } 
          />
          <Route path="/" element={<Navigate to="/dashboard" replace />} />
          <Route path="*" element={<Navigate to="/dashboard" replace />} />
        </Routes>
      </Router>
    </AuthProvider>
  );
}

import { 
  LayoutDashboardIcon,
  ReceiptIcon,
  SettingsIcon,
  LightbulbIcon,
  LogOutIcon,
  WalletIcon,
  XIcon,
  UsersIcon,
  ChevronRightIcon,
  RepeatIcon,
  BarChart3Icon,
  CalendarIcon,
  ShieldCheckIcon
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';

interface SidebarProps {
  currentTab: string;
  onTabChange: (tab: any) => void;
  isOpen?: boolean;
  onClose?: () => void;
}

export function Sidebar({ currentTab, onTabChange, isOpen, onClose }: SidebarProps) {
  const { logout, currentUser } = useAuth();
  const navigate = useNavigate();

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboardIcon },
    { id: 'transactions', label: 'Transactions', icon: ReceiptIcon },
    { id: 'fixed-expenses', label: 'Fixed Expenses', icon: RepeatIcon },
    { id: 'family', label: 'Family Wallet', icon: UsersIcon },
    { id: 'reports', label: 'Reports', icon: BarChart3Icon },
    { id: 'budget-audit', label: 'Budget Audit', icon: ShieldCheckIcon },
    { id: 'yearly-summary', label: 'Year Summary', icon: CalendarIcon },
    { id: 'insights', label: 'Insights', icon: LightbulbIcon },
    { id: 'settings', label: 'Budget Settings', icon: SettingsIcon },
  ];

  const handleLogout = async () => {
    try {
      await logout();
      toast.success('Signed out securely');
      navigate('/login');
    } catch (err) {
      toast.error('Sign out failed');
    }
  };

  const handleTabClick = (id: string) => {
    onTabChange(id);
    if (onClose) onClose();
  };

  const sidebarContent = (
    <div className="flex flex-col h-full bg-slate-900 text-slate-300 border-r border-slate-800/50 shadow-2xl">
      <div className="p-8 flex items-center justify-between">
        <div className="flex items-center gap-3 group transition-all duration-300 transform">
          <div className="premium-gradient p-2.5 rounded-2xl shadow-lg shadow-indigo-500/20 group-hover:scale-110 transition-transform">
            <WalletIcon className="w-6 h-6 text-white" />
          </div>
          <span className="font-black text-2xl text-white tracking-tighter">Tracker</span>
        </div>
        <button 
          onClick={onClose}
          className="md:hidden p-2 -mr-2 text-slate-500 hover:text-white transition-colors"
        >
          <XIcon className="w-6 h-6" />
        </button>
      </div>

      <nav className="flex-1 px-4 py-2 space-y-1 overflow-y-auto custom-scrollbar">
        {navItems.map((item) => {
          const Icon = item.icon;
          const isActive = currentTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => handleTabClick(item.id)}
              className={`w-full flex items-center justify-between group px-4 py-3.5 rounded-2xl transition-all duration-300 ${
                isActive 
                ? 'bg-white/10 text-white font-bold shadow-sm' 
                : 'hover:bg-white/5 hover:text-white'
              }`}
            >
              <div className="flex items-center gap-3.5">
                <Icon className={`w-5 h-5 transition-colors duration-300 ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-slate-300'}`} />
                <span className="text-sm tracking-tight">{item.label}</span>
              </div>
              {isActive && (
                <ChevronRightIcon className="w-4 h-4 text-indigo-400 animate-in slide-in-from-left-2 duration-300" />
              )}
            </button>
          );
        })}
      </nav>

      <div className="p-6 mt-auto">
        <div className="bg-white/5 rounded-3xl p-5 border border-white/5 group hover:bg-white/[0.08] transition-all duration-300">
          <div className="flex items-center gap-3.5 mb-4">
            <div className="w-10 h-10 rounded-2xl premium-gradient flex items-center justify-center text-sm font-black text-white shadow-lg overflow-hidden border-2 border-white/10">
              {currentUser?.photoURL ? (
                <img src={currentUser.photoURL} alt={currentUser.displayName || ''} className="w-full h-full object-cover" />
              ) : (
                currentUser?.displayName?.charAt(0) || currentUser?.email?.charAt(0)
              )}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-black text-white truncate tracking-tight">{currentUser?.displayName || 'Finance Pro'}</p>
              <p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest mt-0.5">Premium Plan</p>
            </div>
          </div>
          <button
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2.5 py-2.5 bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white rounded-xl transition-all duration-300 text-xs font-black uppercase tracking-widest"
          >
            <LogOutIcon className="w-3.5 h-3.5" />
            Sign Out
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <>
      {/* Mobile Drawer Overlay */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-40 md:hidden animate-in fade-in duration-500"
          onClick={onClose}
        />
      )}

      {/* Mobile Sidebar */}
      <aside className={`fixed inset-y-0 left-0 w-72 z-50 md:hidden transform transition-all duration-500 cubic-bezier(0.4, 0, 0.2, 1) ${
        isOpen ? 'translate-x-0 opacity-100' : '-translate-x-full opacity-0'
      }`}>
        {sidebarContent}
      </aside>

      {/* Desktop Sidebar */}
      <aside className="hidden md:flex flex-col w-72 flex-shrink-0">
        {sidebarContent}
      </aside>
    </>
  );
}

import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  onAuthStateChanged, 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signOut, 
  sendPasswordResetEmail, 
  signInWithPopup,
  updateProfile,
  User
} from 'firebase/auth';
import { auth, googleProvider } from '../firebase';

interface AuthContextType {
  currentUser: User | null;
  loading: boolean;
  signup: (email: string, password: string, name: string) => Promise<void>;
  login: (email: string, password: string) => Promise<any>;
  googleLogin: () => Promise<any>;
  logout: () => Promise<any>;
  resetPassword: (email: string) => Promise<any>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  async function signup(email: string, password: string, name: string) {
    const res = await createUserWithEmailAndPassword(auth, email, password);
    await updateProfile(res.user, { displayName: name });
  }

  function login(email: string, password: string) {
    return signInWithEmailAndPassword(auth, email, password);
  }

  function googleLogin() {
    return signInWithPopup(auth, googleProvider);
  }

  function logout() {
    return signOut(auth);
  }

  function resetPassword(email: string) {
    return sendPasswordResetEmail(auth, email);
  }

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const value = {
    currentUser,
    loading,
    signup,
    login,
    googleLogin,
    logout,
    resetPassword
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}

import { useState, useEffect } from 'react';
import {
  collection,
  query,
  where,
  onSnapshot,
  doc,
  orderBy
} from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';
import { AppState, Transaction } from '../types';
import { getCurrentMonthKey } from '../utils/helpers';

export function useAppState() {
  const { currentUser } = useAuth();
  const [currentMonth, setCurrentMonth] = useState(getCurrentMonthKey());
  const [isLoaded, setIsLoaded] = useState(false);
  const [state, setState] = useState<AppState>({
    transactions: [],
    budgets: {},
    savings: 0,
    customCategories: [],
    recurringExpenses: [],
    familyMembers: [],
    appliedRecurringMonths: []
  });

  // 1. Sync User Document (Budgets, Savings, Settings)
  useEffect(() => {
    if (!currentUser) {
      setIsLoaded(true);
      return;
    }

    const userRef = doc(db, "users", currentUser.uid);
    const unsub = onSnapshot(userRef, (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        setState(prev => ({
          ...prev,
          budgets: data.budgets || {},
          savings: data.savings || 0,
          customCategories: data.customCategories || [],
          recurringExpenses: data.recurringExpenses || [],
          familyMembers: data.familyMembers || [],
          appliedRecurringMonths: data.appliedRecurringMonths || []
        }));
      }
      setIsLoaded(true);
    }, (error) => {
      if (error.code === 'permission-denied') {
        console.warn("Using local storage fallback for user profile.");
        const getLocal = (key: string, def: any) => {
          const val = localStorage.getItem(key);
          return val ? JSON.parse(val) : def;
        };
        setState(prev => ({
          ...prev,
          budgets: getLocal('budgets', {}),
          savings: getLocal('savings', 0),
          customCategories: getLocal('customCategories', []),
          recurringExpenses: getLocal('recurringExpenses', []),
          familyMembers: getLocal('familyMembers', []),
        }));
      }
      setIsLoaded(true);
    });

    return () => unsub();
  }, [currentUser]);

  // 2. Sync Transactions
  useEffect(() => {
    if (!currentUser) return;

    const q = query(
      collection(db, "expenses"),
      where("userId", "==", currentUser.uid),
      orderBy("date", "desc")
    );

    const unsub = onSnapshot(q, (snapshot) => {
      const txns = snapshot.docs.map(docSnap => ({
        id: docSnap.id,
        ...docSnap.data()
      })) as Transaction[];
      setState(prev => ({ ...prev, transactions: txns }));
    }, (error) => {
      if (error.code === 'permission-denied') {
        console.warn("Using local storage fallback for transactions.");
        const localTxns = localStorage.getItem('transactions');
        if (localTxns) {
          setState(prev => ({ ...prev, transactions: JSON.parse(localTxns) }));
        }
      }
    });

    return () => unsub();
  }, [currentUser]);

  return { 
    state, 
    setState, 
    currentMonth, 
    setCurrentMonth, 
    isLoaded 
  };
}

import { useMemo } from 'react';
import {
  collection,
  addDoc,
  updateDoc,
  deleteDoc,
  doc,
  serverTimestamp,
  writeBatch,
  setDoc,
  Timestamp
} from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';
import {
  Transaction,
  RecurringExpense,
  FamilyMember,
  FamilyTransaction,
  PaymentMode,
} from '../types';
import {
  getCurrentMonthKey,
} from '../utils/helpers';
import toast from 'react-hot-toast';
import { useAppState } from './useAppState';
import { useFinanceLogic } from './useFinanceLogic';

export function useExpenseTracker() {
  const { currentUser } = useAuth();
  const { state, setState, currentMonth, setCurrentMonth, isLoaded } = useAppState();
  const metrics = useFinanceLogic({ state, currentMonth });

  const categories = useMemo(() => {
    return state.customCategories.length > 0 
      ? state.customCategories 
      : ['Room Rent', 'Food', 'Dress', 'Travel', 'Essentials', 'Miscellaneous'];
  }, [state.customCategories]);

  const availableMonths = useMemo(() => {
    const months = new Set<string>();
    months.add(getCurrentMonthKey());
    state.transactions.forEach((t) => months.add(t.date.substring(0, 7)));
    Object.keys(state.budgets).forEach((m) => months.add(m));
    return Array.from(months).sort().reverse();
  }, [state.transactions, state.budgets]);

  // HELPER: Initialize or Update User Profile with the current state to ensure Firestore existence
  const syncUserProfile = async (updates: Partial<any>) => {
    if (!currentUser) return;
    const userRef = doc(db, "users", currentUser.uid);
    try {
      await setDoc(userRef, updates, { merge: true });
    } catch (error: any) {
      if (error?.code === 'permission-denied') {
        // Fallback strategy: update local state only
        setState(prev => ({ ...prev, ...updates }));
        Object.entries(updates).forEach(([key, val]) => {
          localStorage.setItem(key, JSON.stringify(val));
        });
      } else {
        throw error;
      }
    }
  };

  // ACTIONS
  const addTransaction = async (t: Omit<Transaction, 'id' | 'userId' | 'createdAt' | 'updatedAt'>) => {
    if (!currentUser) return;
    try {
      await addDoc(collection(db, "expenses"), {
        ...t,
        userId: currentUser.uid,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      });
    } catch (error: any) {
      if (error?.code === 'permission-denied') {
        const localId = `local-${Date.now()}`;
        const newTxn: Transaction = {
          ...t,
          id: localId,
          userId: currentUser.uid,
          createdAt: Timestamp.now(),
          updatedAt: Timestamp.now()
        };
        const updatedTxns = [newTxn, ...state.transactions];
        setState(prev => ({ ...prev, transactions: updatedTxns }));
        localStorage.setItem('transactions', JSON.stringify(updatedTxns));
      } else {
        toast.error("Failed to add transaction.");
        throw error;
      }
    }
  };

  const bulkAddTransactions = async (transactions: Omit<Transaction, 'id' | 'userId' | 'createdAt' | 'updatedAt'>[]) => {
    if (!currentUser) return;
    const batchSize = 500;
    const toastId = toast.loading(`Processing ${transactions.length} items...`);

    try {
      for (let i = 0; i < transactions.length; i += batchSize) {
        const batch = writeBatch(db);
        const chunk = transactions.slice(i, i + batchSize);
        chunk.forEach(t => {
          const ref = doc(collection(db, "expenses"));
          batch.set(ref, {
            ...t,
            userId: currentUser.uid,
            createdAt: serverTimestamp(),
            updatedAt: serverTimestamp()
          });
        });
        await batch.commit();
      }
      toast.success("Import successful!", { id: toastId });
    } catch (error: any) {
      toast.error("Import restricted or failed.", { id: toastId });
      throw error;
    }
  };

  const editTransaction = async (id: string, updates: Partial<Transaction>) => {
    if (!currentUser) return;
    const { id: _id, userId: _uid, ...cleanUpdates } = updates as any;
    try {
      await updateDoc(doc(db, "expenses", id), {
        ...cleanUpdates,
        updatedAt: serverTimestamp()
      });
    } catch (error: any) {
      if (error?.code === 'permission-denied') {
        const updatedTxns = state.transactions.map(t => t.id === id ? { ...t, ...updates } : t);
        setState(prev => ({ ...prev, transactions: updatedTxns }));
        localStorage.setItem('transactions', JSON.stringify(updatedTxns));
      } else {
        throw error;
      }
    }
  };

  const deleteTransaction = async (id: string | string[]) => {
    if (!currentUser) return;
    const ids = Array.isArray(id) ? id : [id];
    try {
      if (ids.length === 1) {
        await deleteDoc(doc(db, "expenses", ids[0]));
      } else {
        const batch = writeBatch(db);
        ids.forEach(innerId => {
          batch.delete(doc(db, "expenses", innerId));
        });
        await batch.commit();
      }
    } catch (error: any) {
      if (error?.code === 'permission-denied') {
        const updatedTxns = state.transactions.filter(t => !ids.includes(t.id));
        setState(prev => ({ ...prev, transactions: updatedTxns }));
        localStorage.setItem('transactions', JSON.stringify(updatedTxns));
      } else {
        throw error;
      }
    }
  };

  const updateBudget = async (month: string, budget: number, upiBudget?: number, cashBudget?: number, reason = 'Budget update') => {
    const existing = state.budgets[month];
    const newHistoryEntry = {
      date: new Date().toISOString(),
      previousBudget: existing?.totalBudget || 0,
      newBudget: budget,
      reason
    };

    const updatedBudgets = {
      ...state.budgets,
      [month]: {
        ...(existing || { month, totalBudget: 0, history: [], carryForward: 0, carryForwardToSavings: 0 }),
        totalBudget: budget,
        upiBudget: upiBudget !== undefined ? upiBudget : (existing?.upiBudget ?? budget / 2),
        // If cashBudget is not provided, it should absorb the remainder of the total budget to ensure reflection in pools
        cashBudget: cashBudget !== undefined ? cashBudget : (budget - (upiBudget !== undefined ? upiBudget : (existing?.upiBudget ?? budget / 2))),
        history: existing ? [...existing.history, newHistoryEntry] : [newHistoryEntry],
      }
    };

    await syncUserProfile({ budgets: updatedBudgets });
  };

  const transferBetweenModes = async (amount: number, from: 'UPI' | 'Cash') => {
    const existing = state.budgets[currentMonth];
    if (!existing) return toast.error("Budget not set for this month");

    const upi = existing.upiBudget || 0;
    const cash = existing.cashBudget || 0;

    let updatedUpi = upi;
    let updatedCash = cash;

    if (from === 'Cash') {
      if (cash < amount) return toast.error("Insufficient Cash budget");
      updatedUpi += amount;
      updatedCash -= amount;
    } else {
      if (upi < amount) return toast.error("Insufficient UPI budget");
      updatedUpi -= amount;
      updatedCash += amount;
    }

    const updatedBudgets = {
      ...state.budgets,
      [currentMonth]: {
        ...existing,
        upiBudget: updatedUpi,
        cashBudget: updatedCash,
      }
    };

    await syncUserProfile({ budgets: updatedBudgets });
    toast.success(`Transferred ₹${amount} from ${from} to ${from === 'Cash' ? 'UPI' : 'Cash'}`);
  };

  const addMissingAmount = async (amount: number, mode: 'UPI' | 'Cash', notes = '') => {
    await addTransaction({
      title: 'Missing Amount (Discrepancy)',
      amount,
      category: 'Miscellaneous',
      paymentMode: mode,
      date: new Date().toISOString().split('T')[0],
      notes: notes || 'Automatically adjusted for missing funds',
    });
    toast.success(`₹${amount} recorded as missing ${mode}`);
  };

  const updateMissingAmount = async (month: string, amount: number) => {
    const existing = state.budgets[month];
    const updatedBudgets = {
      ...state.budgets,
      [month]: {
        ...(existing || { month, totalBudget: 0, history: [], carryForward: 0, carryForwardToSavings: 0 }),
        missingAmountOverride: amount
      }
    };
    await syncUserProfile({ budgets: updatedBudgets });
    toast.success(`Missing amount updated for ${month}`);
  };

  const carryForwardBudget = async (amount: number, target: 'budget' | 'savings') => {
    const existingBudget = state.budgets[currentMonth];
    const updatedBudgets = { ...state.budgets };
    let updatedSavings = state.savings;

    if (target === 'budget') {
      const currentTotal = existingBudget?.totalBudget || 0;
      const historyEntry = {
        date: new Date().toISOString(),
        previousBudget: currentTotal,
        newBudget: currentTotal + amount,
        reason: `Carry forward from previous month`
      };

      updatedBudgets[currentMonth] = {
        ...(existingBudget || { month: currentMonth, totalBudget: 0, history: [], carryForward: 0, carryForwardToSavings: 0 }),
        totalBudget: currentTotal + amount,
        carryForward: amount,
        history: existingBudget ? [...existingBudget.history, historyEntry] : [historyEntry]
      };
    } else {
      updatedSavings += amount;
      if (existingBudget) {
        updatedBudgets[currentMonth] = {
          ...existingBudget,
          carryForwardToSavings: (existingBudget.carryForwardToSavings || 0) + amount
        };
      }
    }

    await syncUserProfile({ budgets: updatedBudgets, savings: updatedSavings });
    toast.success(target === 'budget' ? `₹${amount} added to budget!` : `₹${amount} saved!`);
  };

  const updateSavings = async (newSavings: number) => {
    await syncUserProfile({ savings: newSavings });
  };

  const addCustomCategory = async (name: string) => {
    const trimmed = name.trim();
    if (trimmed && !categories.includes(trimmed)) {
      const updatedCategories = [...state.customCategories, trimmed];
      await syncUserProfile({ customCategories: updatedCategories });
    }
  };

  const deleteCustomCategory = async (name: string) => {
    const updatedCategories = state.customCategories.filter(c => c !== name);
    await syncUserProfile({ customCategories: updatedCategories });
  };

  const addRecurringExpense = async (expense: Omit<RecurringExpense, 'id' | 'createdAt' | 'isActive'>) => {
    const newRecurring: RecurringExpense = {
      ...expense,
      id: crypto.randomUUID(),
      isActive: true,
      createdAt: Date.now()
    };
    await syncUserProfile({ recurringExpenses: [...state.recurringExpenses, newRecurring] });
  };

  const editRecurringExpense = async (id: string, updates: Partial<RecurringExpense>) => {
    const updated = state.recurringExpenses.map(r => r.id === id ? { ...r, ...updates } : r);
    await syncUserProfile({ recurringExpenses: updated });
  };

  const toggleRecurringExpense = async (id: string) => {
    const updated = state.recurringExpenses.map(r => r.id === id ? { ...r, isActive: !r.isActive } : r);
    await syncUserProfile({ recurringExpenses: updated });
  };

  const deleteRecurringExpense = async (id: string) => {
    const updated = state.recurringExpenses.filter(r => r.id !== id);
    await syncUserProfile({ recurringExpenses: updated });
  };

  // FAMILY WALLET ACTIONS
  const addFamilyMember = async (name: string, initialBalance = 0) => {
    const newMember: FamilyMember = {
      id: crypto.randomUUID(),
      name: name.trim(),
      balance: initialBalance,
      transactions: initialBalance > 0 ? [{
        id: crypto.randomUUID(),
        type: 'deposit',
        amount: initialBalance,
        description: 'Initial balance',
        date: new Date().toISOString().split('T')[0]
      }] : [],
      createdAt: Date.now()
    };
    await syncUserProfile({ familyMembers: [...state.familyMembers, newMember] });
    toast.success(`${name} joined family wallet!`);
  };

  const removeFamilyMember = async (id: string) => {
    const updatedMembers = state.familyMembers.filter(m => m.id !== id);
    await syncUserProfile({ familyMembers: updatedMembers });
  };

  const modifyFamilyMemberAmount = async (id: string, amount: number, type: 'deposit' | 'withdraw', description = '', date?: string, mode?: string, notes?: string) => {
    const updated = state.familyMembers.map(m => {
      if (m.id !== id) return m;
      const newBalance = type === 'deposit' ? m.balance + amount : Math.max(0, m.balance - amount);
      const txn: FamilyTransaction = {
        id: crypto.randomUUID(),
        type,
        amount,
        description: description || (type === 'deposit' ? 'Refill' : 'Expense'),
        date: date || new Date().toISOString().split('T')[0],
        paymentMode: mode as PaymentMode,
        notes: notes
      };
      return { ...m, balance: newBalance, transactions: [...m.transactions, txn] };
    });
    await syncUserProfile({ familyMembers: updated });
  };

  const transferBetweenFamily = async (fromId: string, toId: string, amount: number, date?: string, mode?: string, description?: string) => {
    const fromMember = state.familyMembers.find(m => m.id === fromId);
    if (!fromMember || fromMember.balance < amount) return toast.error('Insufficient funds');

    const targetMember = state.familyMembers.find(m => m.id === toId);
    const txnDate = date || new Date().toISOString().split('T')[0];

    const updated = state.familyMembers.map(m => {
      if (m.id === fromId) {
        const txn: FamilyTransaction = { id: crypto.randomUUID(), type: 'transfer_out', amount, description: description || `Transfer to ${targetMember?.name}`, date: txnDate, paymentMode: mode as PaymentMode, relatedMemberId: toId, relatedMemberName: targetMember?.name };
        return { ...m, balance: m.balance - amount, transactions: [...m.transactions, txn] };
      }
      if (m.id === toId) {
        const txn: FamilyTransaction = { id: crypto.randomUUID(), type: 'transfer_in', amount, description: description || `Transfer from ${fromMember.name}`, date: txnDate, paymentMode: mode as PaymentMode, relatedMemberId: fromId, relatedMemberName: fromMember.name };
        return { ...m, balance: m.balance + amount, transactions: [...m.transactions, txn] };
      }
      return m;
    });
    await syncUserProfile({ familyMembers: updated });
  };

  const transferFamilyToMain = async (memberId: string, amount: number, date?: string, mode?: string, notes?: string) => {
    const member = state.familyMembers.find(m => m.id === memberId);
    if (!member || member.balance < amount) return;
    const txnDate = date || new Date().toISOString().split('T')[0];
    const updatedFamily = state.familyMembers.map(m => {
      if (m.id === memberId) {
        const txn: FamilyTransaction = { id: crypto.randomUUID(), type: 'withdraw', amount, description: 'Move to Main Wallet', date: txnDate, paymentMode: mode as PaymentMode, notes };
        return { ...m, balance: m.balance - amount, transactions: [...m.transactions, txn] };
      }
      return m;
    });
    await syncUserProfile({ familyMembers: updatedFamily });
    await updateBudget(currentMonth, metrics.currentBudget + amount, undefined, undefined, `Transfer from ${member.name}`);
  };

  const transferMainToFamily = async (memberId: string, amount: number, date?: string, mode?: string, notes?: string) => {
    const member = state.familyMembers.find(m => m.id === memberId);
    if (!member) return;
    if (metrics.currentBudget < amount) return toast.error('Exceeds current month budget');
    const txnDate = date || new Date().toISOString().split('T')[0];
    const updatedFamily = state.familyMembers.map(m => {
      if (m.id === memberId) {
        const txn: FamilyTransaction = { id: crypto.randomUUID(), type: 'deposit', amount, description: 'Refill from Main', date: txnDate, paymentMode: mode as PaymentMode, notes };
        return { ...m, balance: m.balance + amount, transactions: [...m.transactions, txn] };
      }
      return m;
    });
    await syncUserProfile({ familyMembers: updatedFamily });
    await updateBudget(currentMonth, Math.max(0, metrics.currentBudget - amount), undefined, undefined, `Sent to ${member.name}`);
  };

  const syncLocalData = async () => {
    const localData = localStorage.getItem('transactions');
    if (!localData || !currentUser) return;
    const txns = JSON.parse(localData);
    if (txns.length === 0) return;

    const toastId = toast.loading("Cloud syncing...");
    try {
      const batch = writeBatch(db);
      txns.forEach((t: any) => {
        const ref = doc(collection(db, "expenses"));
        const { id: _id, ...data } = t;
        batch.set(ref, { ...data, userId: currentUser.uid, createdAt: serverTimestamp(), updatedAt: serverTimestamp() });
      });
      await batch.commit();
      localStorage.removeItem('transactions');
      toast.success("Synced!", { id: toastId });
      setTimeout(() => window.location.reload(), 1500);
    } catch {
      toast.error("Sync failed.", { id: toastId });
    }
  };

  return {
    state,
    isLoaded,
    currentMonth,
    setCurrentMonth,
    categories,
    availableMonths,
    hasLocalData: localStorage.getItem('transactions') !== null && JSON.parse(localStorage.getItem('transactions') || '[]').length > 0,

    // Spread Metrics
    ...metrics,

    // Actions
    addTransaction,
    bulkAddTransactions,
    editTransaction,
    deleteTransaction,
    updateBudget,
    carryForwardBudget,
    updateSavings,
    addCustomCategory,
    deleteCustomCategory,
    addRecurringExpense,
    editRecurringExpense,
    deleteRecurringExpense,
    toggleRecurringExpense,
    addFamilyMember,
    removeFamilyMember,
    modifyFamilyMemberAmount,
    transferBetweenFamily,
    transferFamilyToMain,
    transferMainToFamily,
    transferBetweenModes,
    addMissingAmount,
    updateMissingAmount,
    syncLocalData
  };
}

import "./index.css";

import { createRoot } from "react-dom/client";
import { App } from "./App";

const container = document.getElementById("root");
const root = createRoot(container!);
root.render(<App />);

import { useState } from 'react';
import { Card, CardContent } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { 
  SettingsIcon, 
  PlusIcon, 
  Trash2Icon, 
  HistoryIcon, 
  TargetIcon,
  TagIcon,
  CheckCircle2Icon,
  PlusCircleIcon,
  MinusCircleIcon,
  ArrowRightIcon,
  TrendingUpIcon,
  TrendingDownIcon,
  PiggyBankIcon,
  ArrowDownCircleIcon,
  WalletIcon,
  SparklesIcon,
  SmartphoneIcon,
  BanknoteIcon
} from 'lucide-react';
import { formatCurrency, formatDate } from '../utils/helpers';
import { MonthlyBudget } from '../types';
import toast from 'react-hot-toast';

interface BudgetSettingsProps {
  currentMonth: string;
  monthlyBudget: MonthlyBudget | null;
  categories: string[];
  onUpdateBudget: (month: string, budget: number, upiBudget?: number, cashBudget?: number, reason?: string) => Promise<void>;
  onAddCategory: (name: string) => void;
  onDeleteCategory?: (name: string) => void;
  previousMonthRemaining?: number;
  onCarryForward?: (amount: number, target: 'budget' | 'savings') => void;
  savings?: number;
  onUpdateSavings?: (amount: number) => void;
  onTransferModes?: (amount: number, from: 'UPI' | 'Cash') => Promise<void>;
  upiBudget?: number;
  cashBudget?: number;
}

export function BudgetSettings({ 
  currentMonth, 
  monthlyBudget, 
  categories,
  onUpdateBudget,
  onAddCategory,
  onDeleteCategory,
  previousMonthRemaining = 0,
  onCarryForward,
  savings = 0,
  onUpdateSavings,
  onTransferModes,
  upiBudget = 0,
  cashBudget = 0
}: BudgetSettingsProps) {
  const [newBudget, setNewBudget] = useState(monthlyBudget?.totalBudget.toString() || '0');
  const [newCategory, setNewCategory] = useState('');

  // Quick adjust states
  const [adjustMode, setAdjustMode] = useState<'add' | 'remove'>('add');
  const [adjustAmount, setAdjustAmount] = useState('');
  const [quickNote, setQuickNote] = useState('');

  // Carry forward states
  const [carryForwardAmount, setCarryForwardAmount] = useState(previousMonthRemaining.toString());
  const [carryTarget, setCarryTarget] = useState<'budget' | 'savings'>('budget');

  // Savings adjust
  const [savingsAdjust, setSavingsAdjust] = useState('');

  // Transfer states
  const [transferAmount, setTransferAmount] = useState('');
  const [transferMode, setTransferMode] = useState<'Cash' | 'UPI'>('Cash'); // from
  const [newUpiBudget, setNewUpiBudget] = useState(monthlyBudget?.upiBudget?.toString() || '0');

  const currentBudgetAmount = monthlyBudget?.totalBudget || 0;
  const alreadyCarriedForward = (monthlyBudget?.carryForward || 0) + (monthlyBudget?.carryForwardToSavings || 0);

  const handleUpdateBudget = () => {
    const amount = parseFloat(newBudget);
    if (!isNaN(amount) && amount >= 0) {
      onUpdateBudget(currentMonth, amount, undefined, undefined, 'Full update');
    }
  };

  const handleUpdateDetailedBudget = () => {
    const total = parseFloat(newBudget);
    const upi = parseFloat(newUpiBudget);
    if (!isNaN(total) && !isNaN(upi) && total >= 0 && upi >= 0 && upi <= total) {
      onUpdateBudget(currentMonth, total, upi, total - upi, 'Detailed allocation update');
    } else if (upi > total) {
      toast.error("UPI budget cannot exceed total budget");
    }
  };

  const handleTransfer = () => {
    const amount = parseFloat(transferAmount);
    if (!isNaN(amount) && amount > 0 && onTransferModes) {
      onTransferModes(amount, transferMode);
      setTransferAmount('');
    }
  };


  const handleAddToBudget = () => {
    const amount = parseFloat(adjustAmount);
    if (!isNaN(amount) && amount > 0) {
      const newTotal = currentBudgetAmount + amount;
      onUpdateBudget(currentMonth, newTotal, undefined, undefined, quickNote.trim() || 'Budget added');
      setAdjustAmount('');
      setQuickNote('');
      setNewBudget(newTotal.toString());
    }
  };

  const handleRemoveFromBudget = () => {
    const amount = parseFloat(adjustAmount);
    if (!isNaN(amount) && amount > 0) {
      const newTotal = Math.max(0, currentBudgetAmount - amount);
      onUpdateBudget(currentMonth, newTotal, undefined, undefined, quickNote.trim() || 'Budget removed');
      setAdjustAmount('');
      setQuickNote('');
      setNewBudget(newTotal.toString());
    }
  };

  const handleAddCategory = () => {
    if (newCategory.trim()) {
      onAddCategory(newCategory.trim());
      setNewCategory('');
    }
  };

  const handleCarryForward = () => {
    const amount = parseFloat(carryForwardAmount);
    if (!isNaN(amount) && amount > 0 && onCarryForward) {
      onCarryForward(Math.min(amount, previousMonthRemaining), carryTarget);
      setCarryForwardAmount('0');
    }
  };

  const handleAddToSavings = () => {
    const amount = parseFloat(savingsAdjust);
    if (!isNaN(amount) && amount > 0 && onUpdateSavings) {
      onUpdateSavings(savings + amount);
      setSavingsAdjust('');
    }
  };

  const handleRemoveFromSavings = () => {
    const amount = parseFloat(savingsAdjust);
    if (!isNaN(amount) && amount > 0 && onUpdateSavings) {
      onUpdateSavings(Math.max(0, savings - amount));
      setSavingsAdjust('');
    }
  };

  // Computed preview values
  const adjustNum = parseFloat(adjustAmount) || 0;
  const previewNewBudget = adjustMode === 'add'
    ? currentBudgetAmount + adjustNum
    : Math.max(0, currentBudgetAmount - adjustNum);
  const isValidAdjust = adjustNum > 0;
  const wouldGoNegative = adjustMode === 'remove' && adjustNum > currentBudgetAmount;

// Removed defaultCategories which are now handled in useExpenseTracker

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Budget Settings</h1>
          <p className="text-slate-500 text-sm">Control your spending limits, savings and categories</p>
        </div>
        <div className="bg-white p-2 px-4 rounded-xl border border-slate-200 shadow-sm flex items-center gap-2 self-start sm:self-auto">
          <SettingsIcon className="w-4 h-4 text-indigo-600" />
          <span className="font-bold text-slate-700">Settings</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="space-y-6">
          {/* Set Full Budget Card */}
          <Card className="overflow-hidden border-none shadow-md">
            <div className="bg-indigo-600 p-4 flex flex-col sm:flex-row sm:items-center justify-between text-white gap-2">
              <div className="flex items-center gap-2">
                <TargetIcon className="w-5 h-5 text-indigo-200" />
                <h3 className="font-bold">Monthly Budget</h3>
              </div>
              <span className="text-sm font-medium bg-white/20 px-3 py-1 rounded-full w-fit">{currentMonth}</span>
            </div>
            <CardContent className="p-6">
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Total Budget Amount (₹)</label>
                  <div className="flex gap-2">
                    <Input
                      type="number"
                      placeholder="Total Budget"
                      value={newBudget}
                      onChange={(e) => setNewBudget(e.target.value)}
                      className="flex-1"
                    />
                    <Button onClick={handleUpdateBudget}>Update</Button>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">UPI Allocation (₹)</label>
                    <Input
                      type="number"
                      placeholder="UPI portion"
                      value={newUpiBudget}
                      onChange={(e) => setNewUpiBudget(e.target.value)}
                      className="w-full"
                    />
                  </div>
                  <div className="flex flex-col justify-end">
                    <Button onClick={handleUpdateDetailedBudget} className="w-full">Set Allocation</Button>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="p-4 bg-indigo-50/50 rounded-xl border border-indigo-100/50">
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">
