                  </div>
                  <ArrowRightIcon className="w-4 h-4 text-slate-300" />
                  <div className="flex-1 flex flex-col text-right">
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Target Flow</span>
                    <span className="text-sm font-bold text-indigo-600">{transferMode === 'Cash' ? 'UPI' : 'Cash'}</span>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Existing Budget Change History */}
          <Card className="shadow-sm h-fit">
          <div className="p-4 border-b border-slate-100 flex items-center gap-2">
            <HistoryIcon className="w-5 h-5 text-indigo-600" />
            <h3 className="font-bold text-slate-900">Budget Change History</h3>
          </div>
          <CardContent className="p-0">
            {monthlyBudget?.history && monthlyBudget.history.length > 0 ? (
              <div className="divide-y divide-slate-100">
                {monthlyBudget.history.slice().reverse().map((entry: any, idx: number) => (
                  <div key={idx} className="p-4 hover:bg-slate-50 transition-colors">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-medium text-slate-400">{formatDate(entry.date)}</span>
                      <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${
                        entry.newBudget > entry.previousBudget
                          ? 'bg-emerald-100 text-emerald-700'
                          : entry.newBudget < entry.previousBudget
                            ? 'bg-rose-100 text-rose-700'
                            : 'bg-slate-100 text-slate-600'
                      }`}>
                        {entry.newBudget > entry.previousBudget
                          ? 'Increased'
                          : entry.newBudget < entry.previousBudget
                            ? 'Decreased'
                            : 'Set'}
                      </span>
                    </div>
                    {entry.reason && (
                      <p className="text-xs text-slate-500 mb-1">{entry.reason}</p>
                    )}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="text-sm line-through text-slate-400">{formatCurrency(entry.previousBudget)}</span>
                        <ArrowRightIcon className="w-3 h-3 text-slate-300" />
                        <span className="text-sm font-bold text-slate-900">{formatCurrency(entry.newBudget)}</span>
                      </div>
                      {entry.newBudget !== entry.previousBudget && (
                        <span className={`text-xs font-semibold ${
                          entry.newBudget > entry.previousBudget ? 'text-emerald-600' : 'text-rose-600'
                        }`}>
                          {entry.newBudget > entry.previousBudget ? '+' : '−'}
                          {formatCurrency(Math.abs(entry.newBudget - entry.previousBudget))}
                        </span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="p-12 text-center text-slate-500">
                <HistoryIcon className="w-10 h-10 text-slate-200 mx-auto mb-3" />
                <p>No budget change history recorded yet.</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/Card';
import { KeyIcon, MailIcon, ArrowLeftIcon } from 'lucide-react';
import toast from 'react-hot-toast';

export function ForgotPassword() {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const { resetPassword } = useAuth();

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    try {
      setLoading(true);
      await resetPassword(email);
      toast.success('Check your inbox for further instructions');
    } catch (err: any) {
      toast.error(err.message || 'Failed to reset password');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <div className="mx-auto w-12 h-12 bg-indigo-100 rounded-xl flex items-center justify-center mb-4">
            <KeyIcon className="w-6 h-6 text-indigo-600" />
          </div>
          <CardTitle className="text-2xl font-bold">Forgot Password</CardTitle>
          <p className="text-slate-500 mt-1">Enter your email to reset your password</p>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <Input
              label="Email Address"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@example.com"
              icon={<MailIcon className="w-4 h-4 text-slate-400" />}
              required
            />
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? 'Sending link...' : 'Send Password Reset Link'}
            </Button>
          </form>

          <div className="mt-8 text-center">
            <Link to="/login" title="Return to Login" className="inline-flex items-center text-sm font-medium text-indigo-600 hover:text-indigo-500">
              <ArrowLeftIcon className="w-4 h-4 mr-2" />
              Back to Sign In
            </Link>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useMemo } from 'react';
import { Card, CardContent } from '../components/ui/Card';
import { 
  TrendingUpIcon, 
  TrendingDownIcon, 
  AlertTriangleIcon, 
  CheckCircle2Icon,
  LightbulbIcon,
  ZapIcon,
  ArrowUpRightIcon,
  ArrowDownRightIcon
} from 'lucide-react';
import { formatCurrency, getMonthName } from '../utils/helpers';
import { Transaction } from '../types';

interface InsightsProps {
  transactions: Transaction[];
  currentMonth: string;
  totalBudget: number;
}

export function Insights({ transactions, currentMonth, totalBudget }: InsightsProps) {
  const insights = useMemo(() => {
    const list: any[] = [];
    const thisMonthTransactions = transactions.filter(t => t.date.startsWith(currentMonth));
    const thisMonthTotal = thisMonthTransactions.reduce((sum, t) => sum + t.amount, 0);

    // Get previous month
    const [year, month] = currentMonth.split('-').map(Number);
    const prevMonthDate = new Date(year, month - 2, 1);
    const prevMonthKey = `${prevMonthDate.getFullYear()}-${String(prevMonthDate.getMonth() + 1).padStart(2, '0')}`;
    const prevMonthTransactions = transactions.filter(t => t.date.startsWith(prevMonthKey));
    const prevMonthTotal = prevMonthTransactions.reduce((sum, t) => sum + t.amount, 0);

    // 1. Budget Status
    if (totalBudget > 0) {
      const budgetUsage = (thisMonthTotal / totalBudget) * 100;
      if (budgetUsage > 90) {
        list.push({
          id: 'budget-warning',
          type: 'danger',
          icon: AlertTriangleIcon,
          title: 'Critical Budget Alert',
          message: `You have used ${Math.round(budgetUsage)}% of your monthly budget. Extreme caution advised!`,
          color: 'text-rose-600',
          bg: 'bg-rose-50'
        });
      } else if (budgetUsage > 75) {
        list.push({
          id: 'budget-info',
          type: 'warning',
          icon: AlertTriangleIcon,
          title: 'Budget Threshold Reached',
          message: `You've utilized ${Math.round(budgetUsage)}% of your budget. Keep a close watch on your spending.`,
          color: 'text-amber-600',
          bg: 'bg-amber-50'
        });
      } else {
        list.push({
          id: 'budget-success',
          type: 'success',
          icon: CheckCircle2Icon,
          title: 'Healthy Budgeting',
          message: `You are well within your budget. Keep up the disciplined spending!`,
          color: 'text-emerald-600',
          bg: 'bg-emerald-50'
        });
      }
    }

    // 2. Month-over-Month comparison
    if (prevMonthTotal > 0) {
      const diff = thisMonthTotal - prevMonthTotal;
      const percent = Math.abs((diff / prevMonthTotal) * 100);
      if (diff > 0) {
        list.push({
          id: 'mom-increase',
          type: 'warning',
          icon: TrendingUpIcon,
          title: 'Spending Increased',
          message: `You spent ${formatCurrency(diff)} (${Math.round(percent)}%) more than last month.`,
          color: 'text-amber-600',
          bg: 'bg-amber-50'
        });
      } else {
        list.push({
          id: 'mom-decrease',
          type: 'success',
          icon: TrendingDownIcon,
          title: 'Spending Decreased',
          message: `Awesome! You spent ${formatCurrency(Math.abs(diff))} (${Math.round(percent)}%) less than in ${getMonthName(prevMonthKey)}.`,
          color: 'text-emerald-600',
          bg: 'bg-emerald-50'
        });
      }
    }

    // 3. Category deep dive
    const categoryTotals: Record<string, number> = {};
    thisMonthTransactions.forEach(t => {
      categoryTotals[t.category] = (categoryTotals[t.category] || 0) + t.amount;
    });

    const highestCategory = Object.entries(categoryTotals).sort((a, b) => b[1] - a[1])[0];
    if (highestCategory) {
      list.push({
        id: 'category-insight',
        type: 'info',
        icon: ZapIcon,
        title: 'Top Category Spend',
        message: `Your highest spend this month is in "${highestCategory[0]}" at ${formatCurrency(highestCategory[1])}, which is ${Math.round((highestCategory[1] / thisMonthTotal) * 100)}% of your total spending.`,
        color: 'text-indigo-600',
        bg: 'bg-indigo-50'
      });
    }

    return list;
  }, [transactions, currentMonth, totalBudget]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Financial Insights</h1>
          <p className="text-slate-500">Personalized data-driven tips for your finances</p>
        </div>
        <div className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm flex items-center gap-2">
          <LightbulbIcon className="w-5 h-5 text-amber-500" />
          <span className="font-semibold text-slate-700">Powered by Analysis</span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {insights.length > 0 ? (
          insights.map((insight) => {
            const Icon = insight.icon;
            return (
              <Card key={insight.id} className="overflow-hidden border-none shadow-md">
                <div className={`${insight.bg} p-1 h-2`}></div>
                <CardContent className="p-6">
                  <div className="flex flex-col h-full">
                    <div className="flex items-center gap-3 mb-4">
                      <div className={`${insight.bg} p-2 rounded-lg ${insight.color}`}>
                        <Icon className="w-5 h-5" />
                      </div>
                      <h4 className="font-bold text-slate-900">{insight.title}</h4>
                    </div>
                    <p className="text-slate-600 text-sm leading-relaxed mb-6 flex-1">
                      {insight.message}
                    </p>
                    <div className="flex items-center justify-between pt-4 border-t border-slate-100">
                      <button className="text-xs font-bold text-indigo-600 hover:text-indigo-700 uppercase tracking-wider">
                        Take Action
                      </button>
                      <span className="text-xs text-slate-400 font-medium">Updated just now</span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })
        ) : (
          <div className="col-span-full py-20 text-center">
            <div className="bg-slate-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
              <CompassIcon className="w-8 h-8 text-slate-400" />
            </div>
            <h3 className="text-lg font-bold text-slate-900">Not enough data for insights yet</h3>
            <p className="text-slate-500 mt-2">Add more transactions to unlock powerful financial analysis.</p>
          </div>
        )}
      </div>

      <div className="mt-8">
        <h3 className="text-lg font-bold text-slate-900 mb-4">Spending Patterns</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Card className="hover:shadow-md transition-shadow cursor-pointer">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="bg-indigo-100 p-3 rounded-xl text-indigo-600">
                <ArrowUpRightIcon className="w-6 h-6" />
              </div>
              <div>
                <p className="text-sm font-medium text-slate-500">Upcoming Bill Forecast</p>
                <p className="text-lg font-bold text-slate-900">3 subscriptions detected</p>
              </div>
            </CardContent>
          </Card>
          <Card className="hover:shadow-md transition-shadow cursor-pointer">
