                <ArrowDownRightIcon className="w-6 h-6" />
              </div>
              <div>
                <p className="text-sm font-medium text-slate-500">Potential Savings</p>
                <p className="text-lg font-bold text-slate-900">Save up to ₹1,200 this month</p>
              </div>
