import React, { useState, useMemo } from 'react';
import toast from 'react-hot-toast';
import { Card, CardContent } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { Select } from '../components/ui/Select';
import {
  PlusIcon,
  SearchIcon,
  Edit2Icon,
  Trash2Icon,
  FilterIcon,
  DownloadIcon,
  UploadIcon,
  XIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  SmartphoneIcon,
  ReceiptIcon,
  BanknoteIcon } from
'lucide-react';
import { formatCurrency, formatDate, getCategoryColor, exportToCSV, parseCSV, getCurrentMonthKey } from '../utils/helpers';
import { CSVImportModal } from '../components/CSVImportModal';
import { Transaction, Category } from '../types';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  onAdd: () => void;
  onEdit: (t: Transaction) => void;
  onDelete: (id: string) => void;
  onImport: (ts: Omit<Transaction, 'id' | 'createdAt' | 'userId'>[]) => void;
}

export function Transactions({
  transactions,
  categories,
  onAdd,
  onEdit,
  onDelete,
  onImport
}: TransactionsProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [modeFilter, setModeFilter] = useState<'all' | 'UPI' | 'Cash'>('all');
  const [importPreviewData, setImportPreviewData] = useState<Omit<Transaction, 'id' | 'createdAt' | 'userId'>[]>([]);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  const [dateRangeFilter, setDateRangeFilter] = useState<'all' | 'today' | 'week' | 'month' | 'custom'>('all');
  const [customStartDate, setCustomStartDate] = useState('');
  const [customEndDate, setCustomEndDate] = useState('');
  const [minAmount, setMinAmount] = useState('');
  const [maxAmount, setMaxAmount] = useState('');
  const [sortBy, setSortBy] = useState<'date' | 'amount' | 'title'>('date');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  const handleExport = () => {
    const filename = `expenses-${new Date().toISOString().split('T')[0]}.csv`;
    exportToCSV(filteredTransactions, filename);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      try {
        const parsed = parseCSV(text);
        if (parsed.length > 0) {
          setImportPreviewData(parsed);
          setIsImportModalOpen(true);
        } else {
          alert('No valid transactions found in the CSV.');
        }
      } catch (err: any) {
        alert(`Error parsing CSV: ${err.message}`);
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const confirmImport = async (data: Omit<Transaction, 'id' | 'createdAt' | 'userId'>[]) => {
    try {
      await onImport(data);
      toast.success(`Successfully imported ${data.length} transactions!`);
      clearAllFilters();
      setIsImportModalOpen(false);
      setImportPreviewData([]);
    } catch (err: any) {
      toast.error(`Import failed: ${err.message}`);
    }
  };

  const isDateInRange = (date: string) => {
    const transactionDate = new Date(date);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    switch (dateRangeFilter) {
      case 'all': return true;
      case 'today': return transactionDate.toDateString() === today.toDateString();
      case 'week': {
        const weekAgo = new Date(today);
        weekAgo.setDate(weekAgo.getDate() - 7);
        return transactionDate >= weekAgo;
      }
      case 'month': {
        const monthAgo = new Date(today);
        monthAgo.setMonth(monthAgo.getMonth() - 1);
        return transactionDate >= monthAgo;
      }
      case 'custom': {
        if (!customStartDate || !customEndDate) return true;
        const start = new Date(customStartDate);
        const end = new Date(customEndDate);
        end.setHours(23, 59, 59, 999);
        return transactionDate >= start && transactionDate <= end;
      }
      default: return true;
    }
  };

  const filteredTransactions = useMemo(() => {
    const filtered = transactions.filter((t) => {
      const matchesSearch = t.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (t.notes && t.notes.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesCategory = categoryFilter ? t.category === categoryFilter : true;
      const matchesMode = modeFilter === 'all' ? true : (t.paymentMode === modeFilter || (modeFilter === 'Cash' && !t.paymentMode));
      const matchesDateRange = isDateInRange(t.date);
      const matchesAmountRange = 
        (!minAmount || t.amount >= parseFloat(minAmount)) &&
        (!maxAmount || t.amount <= parseFloat(maxAmount));

      return matchesSearch && matchesCategory && matchesMode && matchesDateRange && matchesAmountRange;
    });

    filtered.sort((a, b) => {
      let comparison = 0;
      switch (sortBy) {
        case 'date': {
          comparison = new Date(a.date).getTime() - new Date(b.date).getTime();
          if (comparison === 0) {
            const timeA = (a.createdAt as any)?.seconds || 0;
            const timeB = (b.createdAt as any)?.seconds || 0;
            comparison = timeA - timeB;
          }
          break;
        }
        case 'amount': comparison = a.amount - b.amount; break;
        case 'title': comparison = a.title.localeCompare(b.title); break;
      }
      return sortOrder === 'asc' ? comparison : -comparison;
    });

    return filtered;
  }, [transactions, searchTerm, categoryFilter, modeFilter, dateRangeFilter, customStartDate, customEndDate, minAmount, maxAmount, sortBy, sortOrder]);

  const clearAllFilters = () => {
    setSearchTerm('');
    setCategoryFilter('');
    setModeFilter('all');
    setDateRangeFilter('all');
    setCustomStartDate('');
    setCustomEndDate('');
    setMinAmount('');
    setMaxAmount('');
    setSortBy('date');
    setSortOrder('desc');
  };

  const hasActiveFilters = searchTerm || categoryFilter || modeFilter !== 'all' || dateRangeFilter !== 'all' || 
