export type Category =
  'Room Rent' |
  'Food' |
  'Dress' |
  'Travel' |
  'Essentials' |
  'Miscellaneous' |
  string;

export type PaymentMode = 'Cash' | 'UPI';

export interface Transaction {
  id: string;
  title: string;
  amount: number;
  category: Category;
  paymentMode: PaymentMode;
  date: string; // YYYY-MM-DD
  notes?: string;
  upiId?: string; // UPI ID or description for UPI payments
  createdAt: any; // Firestore Timestamp
  updatedAt?: any; // Firestore Timestamp
  userId: string;
  isRecurring?: boolean;
  quantity?: number; // Added quantity field
}

export interface BudgetAdjustment {
  date: string;
  previousBudget: number;
  newBudget: number;
  reason?: string;
}

export interface MonthlyBudget {
  month: string; // YYYY-MM
  totalBudget: number;
  upiBudget?: number; // Separate UPI budget allocation
  cashBudget?: number; // Separate Cash budget allocation
  history: BudgetAdjustment[];
  carryForward?: number; // Amount carried forward from previous month
  carryForwardToSavings?: number; // Amount moved to savings instead
  missingAmountOverride?: number; // Manually set missing amount override
}

export interface RecurringExpense {
  id: string;
  title: string;
  amount: number;
  category: Category;
  notes?: string;
  isActive: boolean;
  createdAt: number;
}

export interface FamilyMember {
